def read_project_files() -> dict[str, str]:
    """Decode every file stored in this portable project generator."""

    compressed = base64.b64decode(PROJECT_FILES)
    return json.loads(zlib.decompress(compressed).decode("utf-8"))


def write_project(destination: str) -> Path:
    """Create the project folder and restore every stored file."""

    project_directory = Path(destination).expanduser().resolve() / PROJECT_NAME
    project_directory.mkdir(parents=True, exist_ok=True)
    for relative_path, content in read_project_files().items():
        target = project_directory / relative_path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(content, encoding="utf-8")

    (project_directory / "generate_project.py").write_text(
        Path(__file__).read_text(encoding="utf-8"), encoding="utf-8"
    )
    return project_directory


if __name__ == "__main__":
    output = write_project(sys.argv[1] if len(sys.argv) > 1 else ".")
    print(f"Created project: {output}")
